const crypto = require('crypto');
const headers = $json.headers ?? {};
const tokenHeader = headers['x-govhub-token'] || headers['X-GOVHUB-TOKEN'];
const pepper = String($env.GOVHUB_TOKEN_PEPPER || '');
if (!pepper) {
  return [{ json: { route: 'error', statusCode: 500, status: 'internal_error', error_code: 'AUTH_CONFIG_MISSING', message: 'token pepper not configured' } }];
}
if (!tokenHeader || !String(tokenHeader).trim()) {
  return [{ json: { route: 'error', statusCode: 401, status: 'unauthorized', error_code: 'AUTH_INVALID_TOKEN', message: 'missing token' } }];
}
const query = ($json.query && typeof $json.query === 'object') ? $json.query : {};
let body = $json.body ?? {};
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { body = {}; }
}
if (!body || typeof body !== 'object') body = {};
const input = { ...query, ...body };
const repo_key = input.repo_key ? String(input.repo_key).trim() : '';
if (!repo_key) {
  return [{ json: { route: 'error', statusCode: 400, status: 'invalid_request', error_code: 'MISSIONS_NEXT_INVALID_REQUEST', message: 'repo_key is required' } }];
}
const token = String(tokenHeader).trim();
const token_hash = crypto.createHash('sha256').update(token + pepper).digest('hex');
const esc = (value) => String(value).replace(/'/g, "''");
return [{ json: { route: 'valid', repo_key, repo_key_sql: esc(repo_key), token_hash, token_hash_sql: esc(token_hash), lock_ttl_seconds: 900 } }];

const row = Array.isArray($json) ? ($json[0] || {}) : $json;
if (row.auth_status === 'unauthorized') {
  return [{ json: { route: 'error', statusCode: 401, status: 'unauthorized', error_code: 'AUTH_INVALID_TOKEN', message: 'invalid or expired token' } }];
}
if (row.auth_status === 'forbidden') {
  return [{ json: { route: 'error', statusCode: 403, status: 'forbidden', error_code: 'AUTH_SCOPE_FORBIDDEN', message: 'missing scope missions:pull' } }];
}
if (row.auth_status !== 'authorized' || !row.agent_id) {
  return [{ json: { route: 'error', statusCode: 500, status: 'internal_error', error_code: 'AUTH_RESOLUTION_FAILED', message: 'auth resolution failed' } }];
}
const prior = $node['Validate Input + Token Hash'].json;
const esc = (value) => String(value).replace(/'/g, "''");
return [{ json: { route: 'valid', repo_key: prior.repo_key, repo_key_sql: prior.repo_key_sql, agent_id: row.agent_id, agent_id_sql: esc(row.agent_id), lock_ttl_seconds: Number(prior.lock_ttl_seconds || 900) } }];
